css:
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] {
  --primary: #0d5c8c;
  --secondary: #bfe8ff;
  --background: #021224;
  --frame: #e7f7ff;
  background: var(--background);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-water,
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-front {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-water { z-index: 0; }
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-stage {
  position: absolute;
  inset: 0;
  z-index: 2;
  overflow: visible;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-front { z-index: 4; }
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .logo-slot,
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .qr-slot {
  position: absolute;
  z-index: 6;
  pointer-events: none;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .logo-slot {
  top: 3.2%;
  left: 3.2%;
  width: min(14%, 180px);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .qr-slot {
  right: 3.2%;
  bottom: 3.2%;
  width: min(12%, 160px);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .logo-slot img,
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .logo-slot canvas,
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .qr-slot img,
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .qr-slot canvas {
  width: 100%;
  height: auto;
  display: block;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .dyn-card.br-bubble {
  position: absolute;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 50%;
  overflow: hidden;
  background: transparent;
  box-shadow: none;
  left: 0;
  top: 0;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-glass {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  overflow: hidden;
  box-shadow:
    inset 0 0 0 1.5px color-mix(in srgb, var(--frame) 72%, white),
    inset 0 -10px 16px rgba(0, 20, 40, 0.28),
    0 10px 22px rgba(0, 12, 28, 0.25);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-glass img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  transform: scale(1.08);
  transform-origin: 50% 46%;
  animation: br-lens 7s ease-in-out infinite;
  filter: url(#br-lens);
  -webkit-mask-image: radial-gradient(circle at 50% 48%, #000 42%, rgba(0,0,0,0.78) 62%, rgba(0,0,0,0.35) 74%, transparent 86%);
  mask-image: radial-gradient(circle at 50% 48%, #000 42%, rgba(0,0,0,0.78) 62%, rgba(0,0,0,0.35) 74%, transparent 86%);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-shine {
  position: absolute;
  left: 18%;
  top: 12%;
  width: 36%;
  height: 22%;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(255,255,255,0.92), rgba(255,255,255,0) 72%);
  transform: rotate(-22deg);
  pointer-events: none;
  z-index: 2;
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-rim {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  pointer-events: none;
  z-index: 3;
  background:
    radial-gradient(circle at 32% 28%, rgba(255,255,255,0.3), transparent 18%),
    radial-gradient(circle at 50% 50%, transparent 62%, color-mix(in srgb, var(--frame) 42%, transparent) 80%, rgba(255,255,255,0.55) 88%, transparent 94%);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"][data-photo-style="bw"] .dyn-card img {
  filter: grayscale(1) contrast(1.05);
}
#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"][data-photo-style="sepia"] .dyn-card img {
  filter: sepia(0.55) contrast(1.04);
}
@keyframes br-lens {
  0%, 100% { transform: scale(1.06) translate3d(0, 0, 0); }
  50% { transform: scale(1.14) translate3d(1.2%, -1%, 0); }
}

#dyn-mosaic-theme[data-theme="mosaic-bubble-rise"] .br-tint {
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: 50%;
  pointer-events: none;
  background: var(--br-tint, #7ec8ff);
  opacity: var(--br-tint-opacity, 0);
  -webkit-mask-image: radial-gradient(circle at 50% 48%, #000 42%, rgba(0,0,0,0.78) 62%, rgba(0,0,0,0.35) 74%, transparent 86%);
  mask-image: radial-gradient(circle at 50% 48%, #000 42%, rgba(0,0,0,0.78) 62%, rgba(0,0,0,0.35) 74%, transparent 86%);
}
